<script setup lang="ts">import { ref } from 'vue';import { api,post } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';const id=ref('fault-test'),data=ref<any>(),error=ref(''),loading=ref(false);async function act(name:'open'|'preview'){loading.value=true;error.value='';try{data.value=name==='open'?await api(`/scenarios/${id.value}`):await post(`/scenarios/${id.value}/preview`,{})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}</script>
<template><section class="panel"><div class="panel-head"><div><h2>Scenario workspace</h2><p>Versioned timeline with safe fault operators and no Gold fields.</p></div><div class="inline"><input v-model="id"><button @click="act('open')">Open</button><button class="secondary" @click="act('preview')">Preview</button></div></div><AsyncState :loading="loading" :error="error" :empty="!data"><pre>{{data}}</pre></AsyncState></section></template>
